import $ from 'jquery';
import * as Aria from './aria';
import Bootstrap from './index';
import Pending from 'core/pending';
import {DefaultWhitelist} from './bootstrap/tools/sanitizer';
import setupBootstrapPendingChecks from './pending';

/**
 * Rember the last visited tabs.
 */
const rememberTabs = () => {
    $('a[data-toggle="tab"]').on('shown.bs.tab', function(e) {
        var hash = $(e.target).attr('href');
        if (history.replaceState) {
            history.replaceState(null, null, hash);
        } else {
            location.hash = hash;
        }
    });
    const hash = window.location.hash;
    if (hash) {
        const tab = document.querySelector('[role="tablist"] [href="' + hash + '"]');
        if (tab) {
            tab.click();
        }
    }
};

/**
 * Enable all popovers
 *
 */
const enablePopovers = () => {
    $('body').popover({
        container: 'body',
        selector: '[data-toggle="popover"]',
        trigger: 'focus',
        whitelist: Object.assign(DefaultWhitelist, {
            table: [],
            thead: [],
            tbody: [],
            tr: [],
            th: [],
            td: [],
        }),
    });

    // Bootstrap points a shown trigger's aria-describedby at its tip, and removes the tip's 'show'
    // class as soon as it starts hiding, so the two together tell us whether a popover is really
    // open right now. The attribute alone is not enough, since it is only removed once the
    // (animated, therefore deferred) hide has completed.
    const isPopoverShown = popoverTrigger => {
        const tipId = popoverTrigger.getAttribute('aria-describedby');
        const tip = tipId ? document.getElementById(tipId) : null;
        return !!tip && tip.classList.contains('show');
    };

    // Escape is handled in the capture phase so that it reaches the popover before any ancestor
    // of the trigger. core/modal binds its own Escape handling to the modal root, which is an
    // ancestor of a help icon rendered inside a modal, so a bubbling listener here would only
    // run after the modal had already hidden or destroyed itself. Propagation is stopped only
    // when a popover is genuinely open, so Escape still closes the modal when a trigger merely
    // has focus.
    document.addEventListener('keydown', e => {
        if (e.key !== 'Escape') {
            return;
        }
        const popoverTrigger = e.target.closest('[data-toggle="popover"]');
        if (popoverTrigger && isPopoverShown(popoverTrigger)) {
            e.stopPropagation();
            $(popoverTrigger).popover('hide');
        }
    }, true);

    document.addEventListener('keydown', e => {
        if (e.key === 'Enter' && e.target.closest('[data-toggle="popover"]')) {
            $(e.target).popover('show');
        }
    });
    document.addEventListener('click', e => {
        $(e.target).closest('[data-toggle="popover"]').popover('show');
    });
};

/**
 * Enable tooltips
 *
 */
const enableTooltips = () => {
    $('body').tooltip({
        container: 'body',
        selector: '[data-toggle="tooltip"]',
    });
    document.addEventListener('keydown', e => {
        if (e.key === 'Escape') {
            // Hide tooltips on escape key press.
            $('.tooltip').tooltip('hide');
        }
    });
};

const pendingPromise = new Pending('theme_boost/loader:init');

// Add pending promise event listeners to relevant Bootstrap custom events.
setupBootstrapPendingChecks();

// Setup Aria helpers for Bootstrap features.
Aria.init();

// Remember the last visited tabs.
rememberTabs();

// Enable all popovers.
enablePopovers();

// Enable all tooltips.
enableTooltips();

// Disables flipping the dropdowns up or dynamically repositioning them along the Y-axis (based on the viewport)
// to prevent the dropdowns getting hidden behind the navbar or them covering the trigger element.
$.fn.dropdown.Constructor.Default.popperConfig = {
    modifiers: {
        flip: {
            enabled: false,
        },
        storeTopPosition: {
            enabled: true,
            // eslint-disable-next-line no-unused-vars
            fn(data, options) {
                data.storedTop = data.offsets.popper.top;
                return data;
            },
            order: 299
        },
        restoreTopPosition: {
            enabled: true,
            // eslint-disable-next-line no-unused-vars
            fn(data, options) {
                data.offsets.popper.top = data.storedTop;
                return data;
            },
            order: 301
        }
    },
};

pendingPromise.resolve();

export {
    Bootstrap,
};
